const finite=n=>Number.isFinite(n);
export const trialTime=n=>{if(!finite(n))return '—';const ticks=Math.max(0,Math.round(n*100));return Math.floor(ticks/6000)+':'+((ticks%6000)/100).toFixed(2).padStart(5,'0');};
export function trialKey(setup){return [setup.route,setup.level,setup.car,setup.world,...['acceleration','handling','brakes','nitro'].map(k=>setup.spec?.upgradeLevels?.[k]||0)].join('|');}
export function trialSeed(route,level){let seed=2166136261;for(const c of 'trial-v1|'+route+'|'+level)seed=Math.imul(seed^c.charCodeAt(0),16777619);return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t^=t+Math.imul(t^t>>>7,61|t);return ((t^t>>>14)>>>0)/4294967296;};}
export function normalizeTrials(raw){if(!Array.isArray(raw))return [];return raw.filter(r=>r&&typeof r.key==='string'&&r.key.length<180&&finite(r.time)&&r.time>0&&r.time<3600).slice(0,12).map(r=>({...r,path:Array.isArray(r.path)?r.path.filter(p=>Array.isArray(p)&&p.length===5&&p.every(finite)).slice(0,1202):[]}));}
export class TrialRecorder {
 constructor(){this.path=[];this.interval=.15;}
 add(s,final=false){const t=final?s.finishTime:s.time;if(!finite(t))return;const last=this.path.at(-1);if(last&&t<=last[0])return;if(!final&&last&&t-last[0]<this.interval)return;this.path.push([t,s.distance,s.x,(s.jumpY||0)+(s.rampLift||0),s.steering||0]);if(this.path.length>1200){this.path=this.path.filter((_,i)=>i%2===0);this.interval*=2;}}
}
export function ghostPose(record,time){const path=record?.path;if(!path?.length||time<path[0][0]||time>record.time)return null;let lo=0,hi=path.length-1;while(lo+1<hi){const mid=(lo+hi)>>1;if(path[mid][0]<=time)lo=mid;else hi=mid;}const a=path[lo],b=path[hi],mix=Math.max(0,Math.min(1,(time-a[0])/(b[0]-a[0]||1))),v=k=>a[k]+(b[k]-a[k])*mix;return {distance:v(1),x:v(2),jumpY:v(3),steering:v(4)};}
export function ghostTimeAt(record,distance){const path=record?.path;if(!path?.length)return null;let lo=0,hi=path.length-1;while(lo+1<hi){const mid=(lo+hi)>>1;if(path[mid][1]<=distance)lo=mid;else hi=mid;}const a=path[lo],b=path[hi],mix=Math.max(0,Math.min(1,(distance-a[1])/(b[1]-a[1]||1)));return a[0]+(b[0]-a[0])*mix;}
export function finishTrial(profile,state,setup,recorder){const key=trialKey(setup),previous=profile.timeTrials?.find(r=>r.key===key),time=state.finishTime,newBest=!previous||time<previous.time;
 recorder.add(state,true);if(newBest){const entry={key,time,date:new Date().toISOString(),path:recorder.path};profile.timeTrials=[entry,...(profile.timeTrials||[]).filter(r=>r.key!==key)].slice(0,12);}
 return {version:2,mode:'trial',car:setup.car,world:setup.world,route:setup.route,difficulty:setup.level,time,previous:previous?.time??null,best:newBest?time:previous.time,newBest,splits:state.trialSplits||[]};
}
export function renderTrialResults(body,r,{carName,worldName,routeName}){body.replaceChildren();const title=document.createElement('div');title.className='trial-results';const h=document.createElement('h2');h.textContent=r.newBest?'NEW PERSONAL BEST':'TIME TRIAL COMPLETE';const time=document.createElement('strong');time.className='trial-finish-time';time.textContent=trialTime(r.time);const detail=document.createElement('p');detail.textContent=carName(r.car)+' · '+routeName(r.route)+' · '+worldName(r.world)+' · '+r.difficulty;const best=document.createElement('p');best.textContent='BEST '+trialTime(r.best)+(r.previous===null?' · First finish': ' · '+(r.time-r.previous>=0?'+':'−')+Math.abs(r.time-r.previous).toFixed(2)+' s');const splits=document.createElement('div');splits.className='trial-splits';for(const [i,t] of r.splits.entries()){const item=document.createElement('span');item.textContent=(i+1)*.75+' km · '+trialTime(t);splits.append(item);}const note=document.createElement('p');note.textContent='Best times and ghosts are matched to your route, difficulty, car, upgrades and world. Latest 12 records saved on this device.';note.className='results-note';title.append(h,time,detail,best,splits,note);body.append(title);}
